70: export const checkVoiceBroadcastPreConditions = async (
71:     room: Room,
72:     client: MatrixClient,
73:     recordingsStore: VoiceBroadcastRecordingsStore,
74: ): Promise<boolean> => {
75:     if (recordingsStore.getCurrent()) {
76:         showAlreadyRecordingDialog();
77:         return false;
78:     }
79: 
80:     const currentUserId = client.getUserId();
81: 
82:     if (!currentUserId) return false;
83: 
84:     if (!room.currentState.maySendStateEvent(VoiceBroadcastInfoEventType, currentUserId)) {
85:         showInsufficientPermissionsDialog();
86:         return false;
87:     }
88: 
89:     const { hasBroadcast, startedByUser } = await hasRoomLiveVoiceBroadcast(client, room, currentUserId);
90: 
91:     if (hasBroadcast && startedByUser) {
92:         showAlreadyRecordingDialog();
93:         return false;
94:     }
95: 
96:     if (hasBroadcast) {
97:         showOthersAlreadyRecordingDialog();
98:         return false;
99:     }
100: 
101:     return true;
