 * Remove client information account data events for devices that no longer exist.
 * Frees up account data size for users with many removed devices.
 * @param validDeviceIds - The device ids of the devices that still exist.
 * @param matrixClient - The matrix client to use.
 */
export const pruneClientInformation = (validDeviceIds: string[], matrixClient: MatrixClient): void => {
    if (!validDeviceIds.length) {
        // avoid deleting all client information while the device list is not yet loaded
        return;
    }

    // getAccountData() without an event type returns all account data events
    const accountData = (matrixClient.getAccountData as unknown as () => Record<string, unknown>)();

    for (const type of Object.keys(accountData ?? {})) {
        if (!type.startsWith(CLIENT_INFORMATION_PREFIX)) continue;

        const deviceId = type.slice(CLIENT_INFORMATION_PREFIX.length);
        if (!validDeviceIds.includes(deviceId)) {
            matrixClient.deleteAccountData(type);
        }
    }
};

const sanitizeContentString = (value: unknown): string | undefined =>
    value && typeof value === "string" ? value : undefined;"}

