};", "new_string": "export const pruneClientInformation = (validDeviceIds: string[], matrixClient: MatrixClient): void => {
    if (!validDeviceIds.length) {
        // avoid deleting all client information while the device list is not yet loaded
        return;
    }

    let types: string[];
    try {
        types = getAccountDataEventTypes(matrixClient);
    } catch {
        // account data is not enumerable on this client, do not prune anything
        return;
    }

    for (const type of types) {
        if (!type.startsWith(CLIENT_INFORMATION_PREFIX)) continue;

        const deviceId = type.slice(CLIENT_INFORMATION_PREFIX.length);
        if (!validDeviceIds.includes(deviceId)) {
            void matrixClient.deleteAccountData(type);
        }
    }
};

/**
 * Get the event types of all known account data events.
 */
const getAccountDataEventTypes = (matrixClient: MatrixClient): string[] => {
    // the store keeps a map of type -> event for all account data
    const stored = (matrixClient.store as unknown as { accountData?: Record<string, unknown> } | undefined)?.accountData;
    if (stored) {
        return Object.keys(stored);
    }

    // fall back to getAccountData() without an event type, which returns all account data events
    const accountData = (matrixClient.getAccountData as unknown as () => Record<string, unknown> | undefined)();
    return Object.keys(accountData ?? {});
};"}

